    задание: 'Посчитайте выручку за неделю. В жёлтой клетке B13 напишите формулу с функцией СУММ: =СУММ( и выделите мышью выручку по дням.',
    данные: [['День', 'Выручка, ₽'], ['Понедельник', 18400], ['Вторник', 21300], ['Среда', 19750], ['Четверг', 24100], ['Пятница', 31800], ['Суббота', 27450], ['Воскресенье', 15900]],
    подписи: {A13: 'Итого за неделю'}, цель: 'B13', ждём: д => [сумма(колонка(д, 1))], нужно: [/СУММ\(/],
    подсказки: ['Формула начинается со знака «=». Функция СУММ складывает всё, что в скобках.', 'Внутри скобок — область: от первой клетки выручки до последней, через двоеточие.'],
    ответ: '=СУММ(B5:B11)', ещё: 'Быстрее: встаньте в B13 и нажмите «Сумма» на вкладке «Главная» — область подставится сама.'},
  {имя: 'Среднее, максимум, минимум', знак: null,
    задание: 'По заказам посчитайте средний чек (E5), самый крупный (E6) и самый мелкий заказ (E7) — функциями СРЗНАЧ, МАКС и МИН.',
    данные: [['Заказ', 'Сумма, ₽'], ['№ 101', 1250], ['№ 102', 3480], ['№ 103', 760], ['№ 104', 2190], ['№ 105', 5120], ['№ 106', 1840], ['№ 107', 990], ['№ 108', 2670], ['№ 109', 4310], ['№ 110', 1530]],
    подписи: {D5: 'Средний чек', D6: 'Самый крупный', D7: 'Самый мелкий'}, цель: 'E5:E7',
    ждём: д => { const v = колонка(д, 1); return [сумма(v) / v.length, Math.max(...v), Math.min(...v)]; }, нужно: [/СРЗНАЧ\(/, /МАКС\(/, /МИН\(/],
    подсказки: ['Три функции, по одной в клетке: =СРЗНАЧ(…), =МАКС(…), =МИН(…).', 'В скобках у всех трёх одна и та же область — суммы заказов B5:B14.'],
    ответ: '=СРЗНАЧ(B5:B14), =МАКС(B5:B14), =МИН(B5:B14)', ещё: 'Выделите суммы — строка состояния внизу сразу покажет и среднее, и сумму, без формул.'},
  {имя: 'Абсолютные ссылки: знак $', знак: 'Знак доллара',
    задание: 'Посчитайте сумму со скидкой для каждого товара: цена × количество × (1 − скидка). Скидка одна на всех — в клетке G4. Напишите формулу в D5 и протяните её до D10.',
    данные: [['Товар', 'Цена, ₽', 'Кол-во', 'Со скидкой, ₽'], ['Ручка', 45, 20], ['Тетрадь', 60, 15], ['Степлер', 380, 2], ['Бумага А4', 320, 5], ['Маркер', 95, 8], ['Папка', 70, 12]],
