    данные: [['Менеджер', 'План', 'Факт', 'Статус'], ['Анна', 500, 540], ['Борис', 450, 410], ['Вера', 600, 600], ['Глеб', 380, 395], ['Дина', 520, 470], ['Егор', 400, 455]],
    подписи: {}, цель: 'D5:D10', ждём: д => д.map(р => р[2] >= р[1] ? 'выполнен' : 'не выполнен'), нужно: [/ЕСЛИ\(/],
    подсказки: ['ЕСЛИ(условие; что, если да; что, если нет). Текст — в кавычках.', 'Условие: C5>=B5. Целиком: =ЕСЛИ(C5>=B5;"выполнен";"не выполнен").'],
    ответ: '=ЕСЛИ(C5>=B5;"выполнен";"не выполнен")', ещё: 'Вера сделала ровно план — поэтому «не меньше», то есть >=, а не >.'},
  {имя: 'Считаем по условию: СЧЁТЕСЛИ', знак: null,
    задание: 'Сколько заказов пришло из Москвы? Ответ — в F5, функцией СЧЁТЕСЛИ по столбцу городов.',
    данные: [['Заказ', 'Город', 'Сумма, ₽'], ...ГОРОДА.map((г, i) => ['№ ' + (201 + i), г, СУММЫ[i]])],
    подписи: {E5: 'Заказов из Москвы'}, цель: 'F5', ждём: д => [д.filter(р => р[1] === 'Москва').length], нужно: [/СЧЁТЕСЛИ\(/],
    подсказки: ['СЧЁТЕСЛИ(где искать; что считать).', 'Где — города B5:B16, что — "Москва" в кавычках.'],
    ответ: '=СЧЁТЕСЛИ(B5:B16;"Москва")', ещё: 'Условие может быть и числом: =СЧЁТЕСЛИ(C5:C16;">10000") — заказы крупнее 10 000.'},
  {имя: 'Сумма по условию: СУММЕСЛИ', знак: 'Аналитик',
    задание: 'Посчитайте выручку по городу из клетки E5 (там «Москва»). Ответ — в F5, функцией СУММЕСЛИ. Поменяете город в E5 — сумма пересчитается.',
    данные: [['Заказ', 'Город', 'Сумма, ₽'], ...ГОРОДА.map((г, i) => ['№ ' + (201 + i), г, СУММЫ[i]])],
    подписи: {E4: 'Город', F4: 'Выручка, ₽', E5: 'Москва'}, цель: 'F5', ждём: (д, всё) => [сумма(д.filter(р => р[1] === всё.E5).map(р => р[2]))], нужно: [/СУММЕСЛИ\(/],
