    ответ: '=A5&" "&ЛЕВСИМВ(B5;1)&". "&ЛЕВСИМВ(C5;1)&"."', ещё: 'То же делает СЦЕПИТЬ(A5;" ";…) — но с & короче.'},
  {имя: 'Даты: сколько дней осталось', знак: 'Знаток дат',
    задание: 'Сколько дней осталось до срока каждой задачи? В C5:C9 вычтите из срока сегодняшнюю дату — функция СЕГОДНЯ. Отрицательное число — срок прошёл.',
    данные: () => { const с = сегодня(); return [['Задача', 'Срок', 'Дней осталось'], ['Отчёт за квартал', с + 6], ['Продление договора', с + 21], ['Сверка с поставщиком', с - 3], ['Инвентаризация', с + 45], ['Оплата аренды', с + 1]]; },
    подписи: {}, форматДанных: {B: 'dd.mm.yyyy'}, цель: 'C5:C9', ждём: д => д.map(р => р[1] - сегодня()), нужно: [/СЕГОДНЯ\(\)/],
    подсказки: ['Дата в таблице — это число дней, поэтому даты можно вычитать.', '=B5-СЕГОДНЯ(). Если вместо числа видна дата — поставьте клетке формат «Общий» или «Целое».'],
    ответ: '=B5-СЕГОДНЯ()', формат: '0', ещё: 'Завтра числа станут на единицу меньше сами: СЕГОДНЯ() пересчитывается каждый день.'},
