  if(вид === 1) return Object.assign(общее, {имя: 'Задача дня: крупные заказы', задание: 'Сколько заказов дороже ' + порог.toLocaleString('ru-RU') + ' ₽? Ответ — в F5.', подписи: {E5: 'дороже ' + порог},
