/* ===== урок на листе ===== */
const номерУрока = т => { const м = /Урок (\d+)\./.exec(String(т || '')); return м ? +м[1] - 1 : -1; };
function разбор(а){ const [x, y] = а.split(':'); const т = s => { const m = /^([A-Z]+)(\d+)$/.exec(s); let c = 0; for(const ch of m[1]) c = c * 26 + ch.charCodeAt(0) - 64; return {r: +m[2] - 1, c: c - 1}; }; const a = т(x), b = т(y || x); return {r1: a.r, c1: a.c, r2: b.r, c2: b.c}; }
async function положитьУрок(у, метка){
