  if(!(await областьПуста(0, 0, данные.length + 12, 8))){
    if(!(await диалог.вопрос('Лист не пуст. Положить урок поверх? Лучше — на новом листе (кнопка «+» внизу, затем откройте панель снова).'))) return false;
  }
  клетка(0, 0).значение = у.имя; клетка(0, 0).стиль = {b: 1, size: 15, color: '#2b5fd9'};
  клетка(1, 0).значение = у.задание; клетка(1, 0).стиль = {wrap: 1, valign: 'top', color: '#1d2433'};
  try { Api.GetActiveSheet().GetRange('A2:H2').Merge(false); } catch(e){}
  высотаСтроки(1, Math.max(40, Math.ceil(у.задание.length / 95) * 20 + 8));
  данные.forEach((ряд, i) => ряд.forEach((v, j) => { const к = клетка(3 + i, j); к.значение = v; к.стиль = i === 0 ? ЗАГ : Object.assign({}, ЯЧ, у.форматДанных && у.форматДанных[БУКВА(j)] ? {fmt: у.форматДанных[БУКВА(j)]} : typeof v === 'number' && !Number.isInteger(v) ? {fmt: '#,##0.00'} : {}); }));
  for(const [а, v] of Object.entries(у.подписи || {})){ const {r1, c1} = разбор(а); const к = клетка(r1, c1); к.значение = v; к.стиль = typeof v === 'number' ? Object.assign({}, ЯЧ, {b: 1, fmt: v < 1 ? '0%' : '#,##0'}) : {b: 1, color: '#3b4252'}; }
  for(let r = ц.r1; r <= ц.r2; r++) for(let c = ц.c1; c <= ц.c2; c++){ const к = клетка(r, c); к.значение = null; к.стиль = Object.assign({}, ЦЕЛЬ, у.формат ? {fmt: у.формат} : {}); }
  [150, 130, 110, 120, 150, 130, 90, 80].forEach((px, c) => ширинаСтолбца(c, px));
  await обновитьВысоты();
  лист().запомнить(ПАМЯТЬ, {метка, данные: данные.length, когда: Date.now()});
  клетка(ц.r1, ц.c1).выделить();
