}
function урокПоМетке(метка){ if(метка === 'день') return задачаДня(); if(/^день-/.test(метка)) return задачаДня(+метка.slice(5)); const i = +метка; return УРОКИ[i] || null; }
async function проверитьНаЛисте(){
  let м = null; try { м = лист().память(ПАМЯТЬ); } catch(e){}
  if(!м) return {нет: true};
  const у = урокПоМетке(м.метка);
  if(!у) return {нет: true};
  const ц = разбор(у.цель);
  const всего = await лист().прочитать(ОБЛАСТЬ(0, 0, Math.max(ц.r2, 3 + м.данные) + 2, 8), {формулы: true});
  const знач = (r, c) => { const v = (всего[r] || [])[c]; return v === undefined ? null : v; };
  const данные = []; for(let i = 1; i < м.данные; i++) данные.push(всего[3 + i] || []);
  const всё = {}; for(const а of Object.keys(у.подписи || {})){ const {r1, c1} = разбор(а); всё[а] = знач(r1, c1); }
  const ждём = у.ждём(данные, всё);
  const ошибки = [], формулы = [];
  let k = 0;
  for(let r = ц.r1; r <= ц.r2; r++) for(let c = ц.c1; c <= ц.c2; c++, k++){
    const v = знач(r, c), ф = String(клетка(r, c).формула || '').replace(/^=/, '').toUpperCase(), е = ждём[k], адр = АДРЕС(r, c);
